   // Owner04Nov: corner drawer numbers +2pt at the established 344px badge reference.
   const corner=wrap.querySelector('.owner-badge-number');
   if(corner){
    const old=Number(corner.getAttribute('font-size')),next=old+2*(4/3)*(badge.frameWidth/344),ratio=next/old;
    const glyphs=[...corner.querySelectorAll('tspan')],anchor=Number(glyphs[0]?.getAttribute('x')||0);
    for(const glyph of glyphs){glyph.setAttribute('x',String(anchor+(Number(glyph.getAttribute('x'))-anchor)*ratio));glyph.setAttribute('textLength',String(Number(glyph.getAttribute('textLength'))*ratio));}
    corner.setAttribute('font-size',String(next));corner.dataset.pointIncrease='2';
   }
   // Owner16Oct: ownership copy is removed; native glyphs move as a rigid group.
   wrap.querySelector('.badge-owner-svg')?.remove();
   const label=wrap.querySelector('.badge-title-svg');
   const titleMoves={"brand-identity":[-33.333333333,29.973807282],"overlays":[-33.333333333,28.937144653],"for-the-table":[-33.333333333,29.92874794],"spatial-design":[-33.333333333,30.178958702],"merchandise":[-33.333333333,30.825871359],"advertisements":[-33.333333333,30.862655213],"music":[-33.333333333,30.862655213],"mvs":[-33.333333333,29.96145079],"episodes":[-33.333333333,30.11631384],"codings":[-33.333333333,30.174329845],"guidelines":[-33.333333333,30.363072557],"templates":[-33.333333333,29.215109417]};
   const move=titleMoves[badge.id];
   if(label&&move){
    let dy=move[1];
    {
     // Owner16Oct: raise eleven titles by1pt; retain the reduced Advertisements.
     // Scale glyph positions and widths uniformly and preserve the ink centre.
     const pointDelta=badge.id==='advertisements'?-1:1;
     const original=Number(label.getAttribute('font-size'));
     const next=original+pointDelta*(4/3)*(badge.frameWidth/344),ratio=next/original;
     const glyphs=Array.from(label.querySelectorAll('tspan')),anchor=Number(glyphs[0].getAttribute('x'));
     const baseline=Number(glyphs[0].getAttribute('y')),originalCenter=314.5-dy;
     for(const glyph of glyphs){glyph.setAttribute('x',String(anchor+(Number(glyph.getAttribute('x'))-anchor)*ratio));glyph.setAttribute('textLength',String(Number(glyph.getAttribute('textLength'))*ratio));}
     label.setAttribute('font-size',String(next));
     dy=314.5-(baseline+(originalCenter-baseline)*ratio);
     if(pointDelta<0)label.dataset.pointReduction='1';
     else label.dataset.pointIncrease='1';
     label.dataset.referenceCanvas='1920';
    }
    label.setAttribute('transform','translate('+move[0]+' '+dy+')');label.dataset.ownerPosition='wing-centered-25pt-left';
   }
   // Keep every beam on a closed clockwise route; the join never reverses travel.
   // Only reflection routes change. The native ring and artwork stay intact.
   for(const beam of wrap.querySelectorAll('.badge-glare-beam')){
    const match=beam.style.offsetPath.match(/^path\((["'])(.*)\1\)$/i);
    if(match){
     let route=match[2].replace(/a\s*216[\s,]+216\s+0\s+1\s+0/gi,'a 216 216 0 1 1');
     if(!/z\s*$/i.test(route))route+=' Z';
     beam.style.offsetPath='none';
     window.DSBorderGlare.fill(beam,route,[...beam.parentNode.children].indexOf(beam)%2?'-3.6s':'0s',1000);
    }
    beam.dataset.glareDirection='clockwise';
   }
   // The upper wing owns its bottom border. The lower top-edge return lies
